package za.ac.univen.clone;
import jakarta.servlet.http.*;
import java.util.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;
import org.springframework.security.oauth2.jwt.*;

@Service
class AccountService {
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(AccountService.class);
 final AccountRepository repository;private final ProviderHttp http;private final Environment env;
 AccountService(AccountRepository repository,ProviderHttp http,Environment env){this.repository=repository;this.http=http;this.env=env;}
 String setting(String name){return env.getProperty("app."+name,"");}
 String origin(){return setting("origin");}
 boolean configured(String provider){return repository.configured()&&Set.of("google","microsoft").contains(provider)&&!setting(provider+"-client-id").isBlank()&&!setting(provider+"-client-secret").isBlank()&&(!provider.equals("microsoft")||setting("microsoft-tenant-id").matches("[0-9a-fA-F-]{36}"));}
 Map<String,Object> account(HttpServletRequest request){var session=request.getSession(false);return session==null?null:repository.get(Data.str(session.getAttribute("account")));}
 Map<String,Object> require(HttpServletRequest request){var account=account(request);if(account==null)throw new ApiProblem(401,"SESSION_EXPIRED","Sign in with Google or Microsoft to access your support calls.");return account;}
 Map<String,Object> summary(Map<String,Object> account){if(account==null)return null;return Data.map("id",account.get("id"),"name",account.get("name"),"email",account.get("email"),"studentNumber",account.get("studentNumber"),"providers",Data.list(account.get("identities")).stream().map(i->Data.map("provider",i.get("provider"),"email",i.get("email"))).toList());}
 void linkStudent(HttpServletRequest request,String number){repository.link(Data.text(require(request),"id"),number);}
 String tokenUrl(String provider){return provider.equals("google")?"https://oauth2.googleapis.com/token":"https://login.microsoftonline.com/"+setting("microsoft-tenant-id")+"/oauth2/v2.0/token";}
 static String random(){byte[] value=new byte[32];new SecureRandom().nextBytes(value);return Base64.getUrlEncoder().withoutPadding().encodeToString(value);}
 record Flow(String provider,String state,String verifier,String nonce,String linkTo,long expires){}
 String start(HttpServletRequest request,String provider,boolean link){if(!configured(provider))throw new ApiProblem(503,"NOT_CONFIGURED","This sign-in is awaiting administrator setup.");var account=account(request);if(link&&account==null)throw new ApiProblem(401,"SESSION_EXPIRED","Sign in before linking another provider.");if(!link&&account!=null)throw new ApiProblem(409,"ACCOUNT_CONFLICT","Use link account to add another sign-in.");String verifier=random(),state=random(),nonce=random();request.getSession(true).setAttribute("oauth",new Flow(provider,state,verifier,nonce,link?Data.text(account,"id"):"",System.currentTimeMillis()+600000));String challenge;try{challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException();}var params=Data.map("client_id",setting(provider+"-client-id"),"response_type","code","redirect_uri",origin()+"/api/account/callback","scope",provider.equals("google")?"openid email profile https://www.googleapis.com/auth/gmail.send https://www.googleapis.com/auth/gmail.readonly":"openid email profile offline_access https://graph.microsoft.com/User.Read https://graph.microsoft.com/Mail.ReadWrite https://graph.microsoft.com/Mail.Send","state",state,"nonce",nonce,"code_challenge",challenge,"code_challenge_method","S256","prompt",provider.equals("google")?"consent select_account":"select_account");if(provider.equals("google"))params.put("access_type","offline");return(provider.equals("google")?"https://accounts.google.com/o/oauth2/v2/auth":"https://login.microsoftonline.com/"+setting("microsoft-tenant-id")+"/oauth2/v2.0/authorize")+"?"+ProviderHttp.form(params);}
 void callback(HttpServletRequest request,String state,String code){var session=request.getSession(false);Object value=session==null?null:session.getAttribute("oauth");if(session!=null)session.removeAttribute("oauth");if(!(value instanceof Flow flow)||flow.expires()<System.currentTimeMillis()||!MessageDigest.isEqual(flow.state().getBytes(StandardCharsets.UTF_8),state.getBytes(StandardCharsets.UTF_8))||code.isBlank())throw new ApiProblem(400,"OAUTH_ERROR","Sign-in expired or was cancelled. Please try again.");if(!flow.linkTo().isBlank()&&!flow.linkTo().equals(Data.str(session.getAttribute("account"))))throw new ApiProblem(401,"SESSION_EXPIRED","Your app session changed while linking accounts.");String provider=flow.provider();LOG.info("oauth_callback_stage=flow_validated provider={}",provider);LOG.info("oauth_callback_stage=token_exchange provider={}",provider);var tokens=http.formPost(tokenUrl(provider),Data.map("grant_type","authorization_code","code",code,"code_verifier",flow.verifier(),"redirect_uri",origin()+"/api/account/callback","client_id",setting(provider+"-client-id"),"client_secret",setting(provider+"-client-secret")));String issuer=provider.equals("google")?"https://accounts.google.com":"https://login.microsoftonline.com/"+setting("microsoft-tenant-id")+"/v2.0";String jwks=provider.equals("google")?"https://www.googleapis.com/oauth2/v3/certs":"https://login.microsoftonline.com/"+setting("microsoft-tenant-id")+"/discovery/v2.0/keys";
    LOG.info("oauth_callback_stage=id_token_verification provider={}",provider);Jwt jwt;try{var decoder=NimbusJwtDecoder.withJwkSetUri(jwks).build();decoder.setJwtValidator(JwtValidators.createDefaultWithIssuer(issuer));jwt=decoder.decode(Data.text(tokens,"id_token"));if(jwt.getSubject()==null||jwt.getIssuedAt()==null||jwt.getExpiresAt()==null||!jwt.getAudience().contains(setting(provider+"-client-id"))||!flow.nonce().equals(jwt.getClaimAsString("nonce"))||(provider.equals("google")&&!Boolean.TRUE.equals(jwt.getClaimAsBoolean("email_verified"))))throw new IllegalArgumentException();}catch(Exception e){throw new ApiProblem(400,"OAUTH_ERROR","The provider identity could not be verified.");}
   LOG.info("oauth_callback_stage=profile_lookup provider={}",provider);var profile=http.request(provider.equals("google")?"https://gmail.googleapis.com/gmail/v1/users/me/profile":"https://graph.microsoft.com/v1.0/me?$select=mail,userPrincipalName,displayName","GET",Data.text(tokens,"access_token"),null);String email=provider.equals("google")?Data.text(profile,"emailAddress"):Data.text(profile,"mail");if(email.isBlank())email=Data.text(profile,"userPrincipalName");email=email.toLowerCase();if(!email.contains("@")||provider.equals("google")&&!email.equalsIgnoreCase(jwt.getClaimAsString("email")))throw new ApiProblem(400,"OAUTH_ERROR","The signed-in identity and mailbox do not match.");var identity=Data.map("provider",provider,"subject",jwt.getSubject(),"name",jwt.getClaimAsString("name")==null?email:jwt.getClaimAsString("name"),"email",email,"accessToken",tokens.get("access_token"),"refreshToken",tokens.get("refresh_token"),"expiresAt",System.currentTimeMillis()+(long)(Data.number(Data.text(tokens,"expires_in"))*1000));LOG.info("oauth_callback_stage=account_persistence provider={}",provider);var account=repository.authenticate(identity,flow.linkTo());request.changeSessionId();session.setAttribute("account",account.get("id"));
 }
 String token(Map<String,Object> account,String provider){var identity=Data.list(account.get("identities")).stream().filter(i->provider.equals(i.get("provider"))).findFirst().orElseThrow(()->new ApiProblem(400,"NOT_CONNECTED","Connect the selected email account first."));if(Data.number(Data.text(identity,"expiresAt"))>System.currentTimeMillis()+60000)return Data.text(identity,"accessToken");String refresh=Data.text(identity,"refreshToken");if(refresh.isBlank())throw new ApiProblem(401,"NOT_CONNECTED","Reconnect your email account.");var tokens=http.formPost(tokenUrl(provider),Data.map("grant_type","refresh_token","refresh_token",refresh,"client_id",setting(provider+"-client-id"),"client_secret",setting(provider+"-client-secret")));identity.put("accessToken",tokens.get("access_token"));if(tokens.containsKey("refresh_token"))identity.put("refreshToken",tokens.get("refresh_token"));identity.put("expiresAt",System.currentTimeMillis()+(long)(Data.number(Data.text(tokens,"expires_in"))*1000));repository.save(account);return Data.text(identity,"accessToken");}
}
